    [6062]={name="Heavy Cord Bracers",quality=1,ilvl=10,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Thwarting Kolkar Aggression'. Pick it over the other reward choices. Starts with Lar Prowltusk in Durotar. Objective: Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.",zone="Durotar",questName="Thwarting Kolkar Aggression",lore="Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."},
    [6095]={name="Wandering Boots",quality=2,ilvl=24,reqLevel=20,sourceType="quest_reward",instructions="Reward from the quest 'Return to Kristoff'. Starts with Brother Paxton in Stormwind City. Objective: Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.",zone="Stormwind City",questName="Return to Kristoff",lore="Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."},
    [6148]={name="Web-covered Boots",quality=1,ilvl=10,reqLevel=5,sourceType="rare_npc",instructions="Drops from Mother Fang.",zone="Elwynn Forest",npc="Mother Fang"},
    [6179]={name="Privateer's Cape",quality=2,ilvl=21,reqLevel=16,sourceType="rare_npc",instructions="Drops from Brack.",zone="Westfall",npc="Brack"},
    [6191]={name="Kimbra Boots",quality=2,ilvl=24,reqLevel=17,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Chok'sul'. Pick it over the other reward choices.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
