    [6321]={name="Silverlaine's Family Seal",quality=3,ilvl=26,reqLevel=21,sourceType="boss_drop",instructions="Drops from Baron Silverlaine.",zone="Shadowfang Keep",npc="Baron Silverlaine"},
    [6324]={name="Robes of Arugal",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Archmage Arugal.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."},
