    [19366]={name="Master Dragonslayer's Orb",quality=4,ilvl=83,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Lord of Blackrock'. Pick it over the other reward choices. Starts with Highlord Bolvar Fordragon in Stormwind City. Objective: Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",zone="Stormwind City",questName="The Lord of Blackrock"},
    [19371]={name="Pendant of the Fallen Dragon",quality=4,ilvl=74,reqLevel=60,sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [19379]={name="Neltharion's Tear",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on.",proc="Equip: Improves your chance to hit by 2.0%."},
    [19382]={name="Pure Elementium Band",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19391]={name="Shimmering Geta",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
