    [19808]={name="Rockhide Strongfish",quality=2,ilvl=45,reqLevel=40,sourceType="object_drop",instructions="Found in Wooden Chair.",npc="Wooden Chair"},
    [19841]={name="Zandalar Confessor's Mantle",quality=4,ilvl=68,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Confessor's Mantle'.",zone="Zul'Gurub",questName="Paragons of Power: The Confessor's Mantle",lore="The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe."},
    [19842]={name="Zandalar Confessor's Bindings",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Confessor's Bindings'.",zone="Zul'Gurub",questName="Paragons of Power: The Confessor's Bindings",lore="Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe."},
    [19843]={name="Zandalar Confessor's Wraps",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Confessor's Wraps'.",zone="Zul'Gurub",questName="Paragons of Power: The Confessor's Wraps",lore="We Zandalar invest power in those who speak with the authority of divinity."},
    [19876]={name="Soul Corrupter's Necklace",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
    [19893]={name="Zanzil's Seal",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Bloodlord Mandokir.",zone="Zul'Gurub",npc="Bloodlord Mandokir"},
