    [23032]={name="Glacial Headdress",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gothik the Harvester.",zone="Naxxramas",npc="Gothik the Harvester",lore="Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."},
    [23036]={name="Necklace of Necropsy",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Heigan the Unclean.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23046]={name="The Restrained Essence of Sapphiron",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",zone="Eastern Plaguelands",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
