    [23057]={name="Gem of Trapped Innocents",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart.",proc="Equip: Improves your chance to get a critical strike by 2.0%."},
    [23061]={name="Ring of Faith",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
